from taf.internal.bmc.interfaces.bmc import BmcResponse


class SystemRm17(object):
    SYSTEM_RESET_PATH = "/redfish/v1/Systems/1/Actions/ComputerSystem.Reset"
    """
    System is a functional sub-component of Bmc Interface,
    Interface implementation composes of sub-components that provide functions on interface.
    """
    def __init__(self, protocol):
        """

        :param protocol: Redfish protocol object
        """
        self.protocol = protocol

    def power_off_immediate(self):
        """
        Perform immediate poweroff reset on system named "1".

        :return: BmcResponse object, with status response and data.
        """
        return self.__computer_system_reset(reset_type="forceoff")

    def power_on(self):
        """
        Power on system named "1".

        :return: BmcResponse object, with status response and data.
        """
        return self.__computer_system_reset(reset_type="on")

    def __computer_system_reset(self, reset_type):
        protocol_response = self.protocol.post(
            path=self.SYSTEM_RESET_PATH,
            body={"Reset_Type": reset_type})
        return BmcResponse(status=protocol_response.status, data=protocol_response.dict)
